structs.Val:
struct Val
{
    TspType t;
    union {
        char *s;
        struct
        {
            double num, den;
        } n;
        struct
        {
            char *name;
            Prim pr;
        } pr;
        struct
        {
            char *name;
            Val args, body;
            Rec env;
        } f;
        struct
        {
            Val car, cdr;
        } p;
        Rec r;
    } v;
}

structs.Tsp:
struct Tsp
{
    char *file;
    size_t filec;
    Val none, nil, t;
    Rec env, strs, syms;
    void **libh;
    size_t libhc;
}

structs.Rec:
typedef struct Rec
{
    int size, cap;
    struct Entry
    {
        char *key;
        Val val;
    } *items;
    struct Rec *next;
} *Rec;

functions.tsp_type_str:
char *tsp_type_str(TspType t)
{
    switch (t)
    {
    case TSP_NONE:
        return "Void";
    case TSP_NIL:
        return "Nil";
    case TSP_INT:
        return "Int";
    case TSP_DEC:
        return "Dec";
    case TSP_RATIO:
        return "Ratio";
    case TSP_STR:
        return "Str";
    case TSP_SYM:
        return "Sym";
    case TSP_PRIM:
        return "Prim";
    case TSP_FORM:
        return "Form";
    case TSP_FUNC:
        return "Func";
    case TSP_MACRO:
        return "Macro";
    case TSP_PAIR:
        return "Pair";
    case TSP_REC:
        return "Rec";
    default:
        if (t == (((TSP_INT | TSP_RATIO) | TSP_DEC) | TSP_SYM | TSP_PAIR))
            return "Expr";
        if (t == (TSP_INT | TSP_RATIO))
            return "Rational";
        if (t & ((TSP_INT | TSP_RATIO) | TSP_DEC))
            return "Num";
        return "Invalid";
    }
}

functions.is_op:
static int is_op(char c)
{
    return strchr("_+-*/\\|=^<>.:", c) != ((void *)0);
}

functions.isnum:
static int isnum(char *str)
{
    return ((*__ctype_b_loc())[(int)((*str))] & (unsigned short int)_ISdigit) ||
           (*str == '.' && ((*__ctype_b_loc())[(int)((str[1]))] & (unsigned short int)_ISdigit)) ||
           ((*str == '-' || *str == '+') &&
            (((*__ctype_b_loc())[(int)((str[1]))] & (unsigned short int)_ISdigit) || str[1] == '.'));
}

functions.skip_ws:
static void skip_ws(Tsp st, int skipnl)
{
    const char *s = skipnl ? " \t\n\r" : " \t";
    while (st->file[st->filec + 0] && (strchr(s, st->file[st->filec + 0]) || st->file[st->filec + 0] == ';'))
    {
        st->filec += strspn(st->file + st->filec, s);
        for (; st->file[st->filec + 0] == ';'; st->filec++)
            st->filec += strcspn(st->file + st->filec, "\n") - !skipnl;
    }
}

functions.tsp_lstlen:
int tsp_lstlen(Val v)
{
    int len = 0;
    for (; v->t == TSP_PAIR; v = ((v)->v.p.cdr))
        len++;
    return ((v)->t == TSP_NIL) ? len : -(len + 1);
}

functions.vals_eq:
static int vals_eq(Val a, Val b)
{
    if (a->t & ((TSP_INT | TSP_RATIO) | TSP_DEC) && b->t & ((TSP_INT | TSP_RATIO) | TSP_DEC))
    {
        if (((a)->v.n.num) != ((b)->v.n.num) || ((a)->v.n.den) != ((b)->v.n.den))
            return 0;
        return 1;
    }
    if (a->t != b->t)
        return 0;
    if (a->t == TSP_PAIR)
        return vals_eq(((a)->v.p.car), ((b)->v.p.car)) && vals_eq(((a)->v.p.cdr), ((b)->v.p.cdr));
    if (a->t & (TSP_FUNC | TSP_MACRO))
        return vals_eq(a->v.f.args, b->v.f.args) && vals_eq(a->v.f.body, b->v.f.body);
    if (a != b)
        return 0;
    return 1;
}

functions.frac_reduce:
static void frac_reduce(int *num, int *den)
{
    int a = abs(*num), b = abs(*den), c = a % b;
    while (c > 0)
    {
        a = b;
        b = c;
        c = a % b;
    }
    *num = *num / b;
    *den = *den / b;
}

functions.hash:
static uint32_t hash(char *key)
{
    uint32_t h = 0;
    char c;
    while (h < (4294967295U) && (c = *key++))
        h = h * 33 + c;
    return h;
}

functions.rec_new:
static Rec rec_new(size_t cap, Rec next)
{
    Rec rec;
    if (!(rec = malloc(sizeof(struct Rec))))
        perror("; malloc"), exit(1);
    rec->size = 0;
    rec->cap = cap;
    if (!(rec->items = calloc(cap, sizeof(struct Entry))))
        perror("; calloc"), exit(1);
    rec->next = next;
    return rec;
}

functions.entry_get:
static Entry entry_get(Rec rec, char *key)
{
    int i = hash(key) % rec->cap;
    char *s;
    while ((s = rec->items[i].key))
    {
        if (!strcmp(s, key))
            break;
        if (++i == rec->cap)
            i = 0;
    }
    return &rec->items[i];
}

functions.rec_get:
static Val rec_get(Rec rec, char *key)
{
    Entry e;
    for (; rec; rec = rec->next)
    {
        e = entry_get(rec, key);
        if (e->key)
            return e->val;
    }
    return ((void *)0);
}

functions.rec_grow:
static void rec_grow(Rec rec)
{
    int i, ocap = rec->cap;
    Entry oitems = rec->items;
    rec->cap *= 2;
    if (!(rec->items = calloc(rec->cap, sizeof(struct Entry))))
        perror("; calloc"), exit(1);
    for (i = 0; i < ocap; i++)
        if (oitems[i].key)
            rec_add(rec, oitems[i].key, oitems[i].val);
    free(oitems);
}

functions.rec_add:
static void rec_add(Rec rec, char *key, Val val)
{
    Entry e = entry_get(rec, key);
    e->val = val;
    if (!e->key)
    {
        e->key = key;
        if (++rec->size > rec->cap / 2)
            rec_grow(rec);
    }
}

functions.rec_extend:
static Rec rec_extend(Rec rec, Val args, Val vals)
{
    Val arg, val;
    int argnum = 2 * tsp_lstlen(args);
    Rec ret = rec_new(argnum > 0 ? argnum : -argnum + 1, rec);
    for (; !((args)->t == TSP_NIL); args = ((args)->v.p.cdr), vals = ((vals)->v.p.cdr))
    {
        if (args->t == TSP_PAIR)
        {
            arg = ((args)->v.p.car);
            val = ((vals)->v.p.car);
        }
        else
        {
            arg = args;
            val = vals;
        }
        if (arg->t != TSP_SYM)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "expected symbol for argument of function definition, recieved '%s'"
                        "\n",
                        tsp_type_str(arg->t));
                return ((void *)0);
            } while (0);
        rec_add(ret, arg->v.s, val);
        if (args->t != TSP_PAIR)
            break;
    }
    return ret;
}

functions.mk_val:
Val mk_val(TspType t)
{
    Val ret;
    if (!(ret = malloc(sizeof(struct Val))))
        perror("; malloc"), exit(1);
    ret->t = t;
    return ret;
}

functions.mk_int:
Val mk_int(int i)
{
    Val ret = mk_val(TSP_INT);
    ((ret)->v.n.num) = i;
    ((ret)->v.n.den) = 1;
    return ret;
}

functions.mk_dec:
Val mk_dec(double d)
{
    Val ret = mk_val(TSP_DEC);
    ((ret)->v.n.num) = d;
    ((ret)->v.n.den) = 1;
    return ret;
}

functions.mk_rat:
Val mk_rat(int num, int den)
{
    Val ret;
    if (den == 0)
        do
        {
            fprintf(stderr, "; tisp: error: "
                            "division by zero"
                            "\n");
            return ((void *)0);
        } while (0);
    frac_reduce(&num, &den);
    if (den < 0)
    {
        den = abs(den);
        num = -num;
    }
    if (den == 1)
        return mk_int(num);
    ret = mk_val(TSP_RATIO);
    ((ret)->v.n.num) = num;
    ((ret)->v.n.den) = den;
    return ret;
}

functions.mk_str:
Val mk_str(Tsp st, char *s)
{
    Val ret;
    if ((ret = rec_get(st->strs, s)))
        return ret;
    ret = mk_val(TSP_STR);
    ret->v.s = s;
    rec_add(st->strs, s, ret);
    return ret;
}

functions.mk_sym:
Val mk_sym(Tsp st, char *s)
{
    Val ret;
    if ((ret = rec_get(st->syms, s)))
        return ret;
    ret = mk_val(TSP_SYM);
    ret->v.s = s;
    rec_add(st->syms, s, ret);
    return ret;
}

functions.mk_prim:
Val mk_prim(TspType t, Prim pr, char *name)
{
    Val ret = mk_val(t);
    ret->v.pr.name = name;
    ret->v.pr.pr = pr;
    return ret;
}

functions.mk_func:
Val mk_func(TspType t, char *name, Val args, Val body, Rec env)
{
    Val ret = mk_val(t);
    ret->v.f.name = name;
    ret->v.f.args = args;
    ret->v.f.body = body;
    ret->v.f.env = env;
    return ret;
}

functions.mk_rec:
Val mk_rec(Tsp st, Rec env, Val assoc)
{
    int cap;
    Val v, ret = mk_val(TSP_REC);
    if (!assoc)
        return ret->v.r = env, ret;
    cap = 2 * tsp_lstlen(assoc);
    ret->v.r = rec_new(cap > 0 ? cap : -cap + 1, ((void *)0));
    Rec r = rec_new(4, env);
    rec_add(r, "this", ret);
    for (Val cur = assoc; cur->t == TSP_PAIR; cur = ((cur)->v.p.cdr))
        if (((cur)->v.p.car)->t == TSP_PAIR && ((((cur)->v.p.car))->v.p.car)->t & (TSP_SYM | TSP_STR))
        {
            if (!(v = tisp_eval(st, r, ((((cur)->v.p.car))->v.p.cdr)->v.p.car)))
                return ((void *)0);
            rec_add(ret->v.r, ((((cur)->v.p.car))->v.p.car)->v.s, v);
        }
        else if (((cur)->v.p.car)->t == TSP_SYM)
        {
            if (!(v = tisp_eval(st, r, ((cur)->v.p.car))))
                return ((void *)0);
            rec_add(ret->v.r, ((cur)->v.p.car)->v.s, v);
        }
        else
            do
            {
                fprintf(stderr, "; tisp: error: "
                                "Rec: missing key symbol or string"
                                "\n");
                return ((void *)0);
            } while (0);
    return ret;
}

functions.mk_pair:
Val mk_pair(Val a, Val b)
{
    Val ret = mk_val(TSP_PAIR);
    ((ret)->v.p.car) = a;
    ((ret)->v.p.cdr) = b;
    return ret;
}

functions.mk_list:
Val mk_list(Tsp st, int n, ...)
{
    Val lst;
    va_list argp;
    __builtin_va_start(argp, n);
    lst = mk_pair(__builtin_va_arg(argp, Val), st->nil);
    for (Val cur = lst; n > 1; n--, cur = ((cur)->v.p.cdr))
        ((cur)->v.p.cdr) = mk_pair(__builtin_va_arg(argp, Val), st->nil);
    __builtin_va_end(argp);
    return lst;
}

functions.read_sign:
static int read_sign(Tsp st)
{
    switch (st->file[st->filec + 0])
    {
    case '-':
        st->filec++;
        return -1;
    case '+':
        st->filec++;
        return 1;
    default:
        return 1;
    }
}

functions.read_int:
static int read_int(Tsp st)
{
    int ret = 0;
    for (; st->file[st->filec + 0] &&
           ((*__ctype_b_loc())[(int)((st->file[st->filec + 0]))] & (unsigned short int)_ISdigit);
         st->filec++)
        ret = ret * 10 + st->file[st->filec + 0] - '0';
    return ret;
}

functions.read_sci:
static Val read_sci(Tsp st, double val, int isint)
{
    if ((__extension__({
            int __res;
            if (sizeof(st->file[st->filec + 0]) > 1)
            {
                if (__builtin_constant_p(st->file[st->filec + 0]))
                {
                    int __c = (st->file[st->filec + 0]);
                    __res = __c < -128 || __c > 255 ? __c : (*__ctype_tolower_loc())[__c];
                }
                else
                    __res = tolower(st->file[st->filec + 0]);
            }
            else
                __res = (*__ctype_tolower_loc())[(int)(st->file[st->filec + 0])];
            __res;
        })) != 'e')
        goto finish;
    st->filec++;
    double sign = read_sign(st) == 1 ? 10.0 : 0.1;
    for (int expo = read_int(st); expo--; val *= sign)
        ;
finish:
    if (isint)
        return mk_int(val);
    return mk_dec(val);
}

functions.read_num:
static Val read_num(Tsp st)
{
    int sign = read_sign(st);
    int num = read_int(st);
    size_t oldc;
    switch (st->file[st->filec + 0])
    {
    case '/':
        if (!isnum(st->file + ++st->filec))
            do
            {
                fprintf(stderr, "; tisp: error: "
                                "incorrect ratio format, no denominator found"
                                "\n");
                return ((void *)0);
            } while (0);
        return mk_rat(sign * num, read_sign(st) * read_int(st));
    case '.':
        st->filec++;
        oldc = st->filec;
        double d = (double)read_int(st);
        int size = st->filec - oldc;
        while (size--)
            d /= 10.0;
        return read_sci(st, sign * (num + d), 0);
    default:
        return read_sci(st, sign * num, 1);
    }
}

functions.esc_char:
static char esc_char(char c)
{
    switch (c)
    {
    case 'n':
        return '\n';
    case 'r':
        return '\r';
    case 't':
        return '\t';
    case '\n':
        return ' ';
    case '\\':
    case '"':
    default:
        return c;
    }
}

functions.esc_str:
static char *esc_str(char *s, int len, int do_esc)
{
    char *pos, *ret;
    if (!(ret = malloc((len + 1) * sizeof(char))))
        perror("; malloc"), exit(1);
    for (pos = ret; pos - ret < len; pos++, s++)
        *pos = (*s == '\\' && do_esc) ? esc_char(*(++s)) : *s;
    *pos = '\0';
    return ret;
}

functions.read_str:
static Val read_str(Tsp st, Val (*mk_fn)(Tsp, char *))
{
    int len = 0;
    char *s = st->file + ++st->filec;
    char endchar = mk_fn == &mk_str ? '"' : '~';
    for (; st->file[st->filec + 0] != endchar; st->filec++, len++)
        if (!st->file[st->filec + 0])
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "reached end before closing %c"
                        "\n",
                        endchar);
                return ((void *)0);
            } while (0);
        else if (st->file[st->filec + 0] == '\\' && st->file[st->filec + -1] != '\\')
            st->filec++;
    st->filec++;
    return mk_fn(st, esc_str(s, len, mk_fn == &mk_str));
}

functions.read_sym:
static Val read_sym(Tsp st, int (*is_char)(char))
{
    int len = 0;
    char *s = st->file + st->filec;
    for (; st->file[st->filec + 0] && is_char(st->file[st->filec + 0]); st->filec++)
        len++;
    return mk_sym(st, esc_str(s, len, 0));
}

functions.read_pair:
Val read_pair(Tsp st, char endchar)
{
    Val v, ret = mk_pair(((void *)0), st->nil);
    int skipnl = endchar != '\n';
    skip_ws(st, skipnl);
    for (Val pos = ret; st->file[st->filec + 0] && st->file[st->filec + 0] != endchar; pos = ((pos)->v.p.cdr))
    {
        if (!(v = tisp_read(st)))
            return ((void *)0);
        if (v->t == TSP_SYM && !strncmp(v->v.s, ".", 2))
        {
            skip_ws(st, skipnl);
            if (!(v = tisp_read(st)))
                return ((void *)0);
            ((pos)->v.p.cdr) = v;
            break;
        }
        ((pos)->v.p.cdr) = mk_pair(v, st->nil);
        skip_ws(st, skipnl);
    }
    skip_ws(st, skipnl);
    if (skipnl && st->file[st->filec + 0] != endchar)
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "did not find closing '%c'"
                    "\n",
                    endchar);
            return ((void *)0);
        } while (0);
    st->filec++;
    return ((ret)->v.p.cdr);
}

functions.tisp_read_sexpr:
Val tisp_read_sexpr(Tsp st)
{
    static char *prefix[] = {
        "'", "quote", "`", "quasiquote", ",@", "unquote-splice", ",", "unquote", "@", "Func", "f\"", "strformat",
    };
    skip_ws(st, 1);
    if (strlen(st->file + st->filec) == 0)
        return st->none;
    if (isnum(st->file + st->filec))
        return read_num(st);
    if (st->file[st->filec + 0] == '"')
        return read_str(st, mk_str);
    if (st->file[st->filec + 0] == '~')
        return read_str(st, mk_sym);
    for (int i = 0; i < (sizeof(prefix) / sizeof((prefix)[0])); i += 2)
    {
        if (!strncmp(st->file + st->filec, prefix[i], strlen(prefix[i])))
        {
            Val v;
            st->filec += strlen(prefix[i]) - (prefix[i][1] == '"');
            if (!(v = tisp_read(st)))
                return ((void *)0);
            return mk_list(st, 2, mk_sym(st, prefix[i + 1]), v);
        }
    }
    if (is_op(st->file[st->filec + 0]))
        return read_sym(st, &is_op);
    if (is_sym(st->file[st->filec + 0]))
        return read_sym(st, &is_sym);
    if (st->file[st->filec + 0] == '(')
        return st->filec++, read_pair(st, ')');
    if (st->file[st->filec + 0] == '[')
        return st->filec++, mk_pair(mk_sym(st, "list"), read_pair(st, ']'));
    if (st->file[st->filec + 0] == '{')
    {
        Val v;
        st->filec++;
        if (!(v = read_pair(st, '}')))
            return ((void *)0);
        return mk_pair(mk_sym(st, "Rec"), v);
    }
    do
    {
        fprintf(stderr,
                "; tisp: error: "
                "could not read given input '%c' (%d)"
                "\n",
                st->file[st->filec], (int)st->file[st->filec]);
        return ((void *)0);
    } while (0);
}

functions.tisp_read:
Val tisp_read(Tsp st)
{
    Val v;
    if (!(v = tisp_read_sexpr(st)))
        return ((void *)0);
    while (st->file[st->filec + 0] == '(' || st->file[st->filec + 0] == ':' || st->file[st->filec + 0] == '>' ||
           st->file[st->filec + 0] == '{')
        v = tisp_read_sugar(st, v);
    return v;
}

functions.tisp_read_sugar:
Val tisp_read_sugar(Tsp st, Val v)
{
    Val lst, w;
    if (st->file[st->filec + 0] == '(')
    {
        st->filec++;
        if (!(lst = read_pair(st, ')')))
            return ((void *)0);
        return mk_pair(v, lst);
    }
    else if (st->file[st->filec + 0] == '{')
    {
        st->filec++;
        if (!(lst = read_pair(st, '}')))
            return ((void *)0);
        return mk_list(st, 3, mk_sym(st, "recmerge"), v, mk_pair(mk_sym(st, "Rec"), lst));
    }
    else if (st->file[st->filec + 0] == ':')
    {
        st->filec++;
        switch (st->file[st->filec + 0])
        {
        case '(':
            st->filec++;
            if (!(w = read_pair(st, ')')))
                return ((void *)0);
            return mk_pair(mk_sym(st, "map"), mk_pair(v, w));
        case ':':
            st->filec++;
            if (!(w = read_sym(st, &is_sym)))
                return ((void *)0);
            return mk_list(st, 2, v, mk_list(st, 2, mk_sym(st, "quote"), w));
        default:
            skip_ws(st, 1);
            if (!(w = tisp_read(st)))
                return ((void *)0);
            return mk_list(st, 2, v, w);
        }
    }
    else if (st->file[st->filec + 0] == '>' && st->file[st->filec + 1] == '>')
    {
        st->filec++, st->filec++;
        if (!(w = tisp_read(st)) || w->t != TSP_PAIR)
            do
            {
                fprintf(stderr, "; tisp: error: "
                                "invalid UFCS"
                                "\n");
                return ((void *)0);
            } while (0);
        return mk_pair(((w)->v.p.car), mk_pair(v, ((w)->v.p.cdr)));
    }
    return v;
}

functions.tisp_read_line:
Val tisp_read_line(Tsp st, int level)
{
    Val pos, ret;
    if (!(ret = read_pair(st, '\n')))
        return ((void *)0);
    if (ret->t != TSP_PAIR)
        ret = mk_pair(ret, st->nil);
    for (pos = ret; ((pos)->v.p.cdr)->t == TSP_PAIR; pos = ((pos)->v.p.cdr))
        ;
    for (; st->file[st->filec + 0]; pos = ((pos)->v.p.cdr))
    {
        int newlevel = strspn(st->file + st->filec, "\t ");
        if (newlevel <= level)
            break;
        st->filec += newlevel;
        ((pos)->v.p.cdr) = mk_pair(tisp_read_line(st, newlevel), ((pos)->v.p.cdr));
    }
    return ((((ret)->v.p.cdr))->t == TSP_NIL) ? ((ret)->v.p.car) : ret;
}

functions.tisp_eval_list:
Val tisp_eval_list(Tsp st, Rec env, Val v)
{
    Val ret = mk_pair(((void *)0), st->nil), ev;
    for (Val cur = ret; !((v)->t == TSP_NIL); v = ((v)->v.p.cdr), cur = ((cur)->v.p.cdr))
    {
        if (v->t != TSP_PAIR)
        {
            if (!(ev = tisp_eval(st, env, v)))
                return ((void *)0);
            ((cur)->v.p.cdr) = ev;
            return ((ret)->v.p.cdr);
        }
        if (!(ev = tisp_eval(st, env, ((v)->v.p.car))))
            return ((void *)0);
        ((cur)->v.p.cdr) = mk_pair(ev, st->nil);
    }
