functions.tisp_eval_body:
Val tisp_eval_body(Tsp st, Rec env, Val v)
{
    Val ret = st->none;
    for (; v->t == TSP_PAIR; v = ((v)->v.p.cdr))
        if (((((v)->v.p.cdr))->t == TSP_NIL) && ((v)->v.p.car)->t == TSP_PAIR)
        {
            Val f, args;
            if (!(f = tisp_eval(st, env, ((((v)->v.p.car))->v.p.car))))
                return ((void *)0);
            if (f->t != TSP_FUNC)
                return eval_proc(st, env, f, ((((v)->v.p.car))->v.p.cdr));
            do
            {
                if (tsp_lstlen(f->v.f.args) > -1 && tsp_lstlen(((((v)->v.p.car))->v.p.cdr)) != tsp_lstlen(f->v.f.args))
                    do
                    {
                        fprintf(stderr,
                                "; tisp: error: "
                                "%s: expected %d argument%s, received %d"
                                "\n",
                                f->v.f.name ? f->v.f.name : "anon", tsp_lstlen(f->v.f.args),
                                tsp_lstlen(f->v.f.args) > 1 ? "s" : "", tsp_lstlen(((((v)->v.p.car))->v.p.cdr)));
                        return ((void *)0);
                    } while (0);
            } while (0);
            if (!(args = tisp_eval_list(st, env, ((((v)->v.p.car))->v.p.cdr))))
                return ((void *)0);
            if (!(env = rec_extend(f->v.f.env, f->v.f.args, args)))
                return ((void *)0);
            v = mk_pair(((void *)0), f->v.f.body);
        }
        else if (!(ret = tisp_eval(st, env, ((v)->v.p.car))))
            return ((void *)0);
    return ret;
}

functions.prepend_bt:
static void prepend_bt(Tsp st, Rec env, Val f)
{
    if (!f->v.f.name)
        return;
    for (; env->next; env = env->next)
        ;
    Entry e = entry_get(env, "bt");
    if (e->val->t == TSP_PAIR && ((e->val)->v.p.car)->t == TSP_SYM &&
        !strncmp(f->v.f.name, ((e->val)->v.p.car)->v.s, strlen(((e->val)->v.p.car)->v.s)))
        return;
    e->val = mk_pair(mk_sym(st, f->v.f.name), e->val);
}

functions.eval_proc:
static Val eval_proc(Tsp st, Rec env, Val f, Val args)
{
    Val ret;
    Rec fenv;
    switch (f->t)
    {
    case TSP_PRIM:
        if (!(args = tisp_eval_list(st, env, args)))
            return ((void *)0);
    case TSP_FORM:
        return (*f->v.pr.pr)(st, env, args);
    case TSP_FUNC:
        if (!(args = tisp_eval_list(st, env, args)))
            return ((void *)0);
    case TSP_MACRO:
        do
        {
            if (tsp_lstlen(f->v.f.args) > -1 && tsp_lstlen(args) != tsp_lstlen(f->v.f.args))
                do
                {
                    fprintf(stderr,
                            "; tisp: error: "
                            "%s: expected %d argument%s, received %d"
                            "\n",
                            f->v.f.name ? f->v.f.name : "anon", tsp_lstlen(f->v.f.args),
                            tsp_lstlen(f->v.f.args) > 1 ? "s" : "", tsp_lstlen(args));
                    return ((void *)0);
                } while (0);
        } while (0);
        if (!(fenv = rec_extend(f->v.f.env, f->v.f.args, args)))
            return ((void *)0);
        if (!(ret = tisp_eval_body(st, fenv, f->v.f.body)))
            return prepend_bt(st, env, f), ((void *)0);
        if (f->t == TSP_MACRO)
            ret = tisp_eval(st, env, ret);
        return ret;
    case TSP_REC:
        if (!(args = tisp_eval_list(st, env, args)))
            return ((void *)0);
        do
        {
            if (1 > -1 && tsp_lstlen(args) != 1)
                do
                {
                    fprintf(stderr,
                            "; tisp: error: "
                            "%s: expected %d argument%s, received %d"
                            "\n",
                            "record", 1, 1 > 1 ? "s" : "", tsp_lstlen(args));
                    return ((void *)0);
                } while (0);
        } while (0);
        do
        {
            if (!(((args)->v.p.car)->t & (TSP_SYM)))
                do
                {
                    fprintf(stderr,
                            "; tisp: error: "
                            "record"
                            ": expected %s, received %s"
                            "\n",
                            tsp_type_str(TSP_SYM), tsp_type_str(((args)->v.p.car)->t));
                    return ((void *)0);
                } while (0);
        } while (0);
        if (!(ret = rec_get(f->v.r, ((args)->v.p.car)->v.s)) && !(ret = rec_get(f->v.r, "else")))
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "could not find element '%s' in record"
                        "\n",
                        ((args)->v.p.car)->v.s);
                return ((void *)0);
            } while (0);
        return ret;
    default:
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "attempt to evaluate non procedural type %s"
                    "\n",
                    tsp_type_str(f->t));
            return ((void *)0);
        } while (0);
    }
}

functions.tisp_eval:
Val tisp_eval(Tsp st, Rec env, Val v)
{
    Val f;
    switch (v->t)
    {
    case TSP_SYM:
        if (!(f = rec_get(env, v->v.s)))
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "could not find symbol '%s'"
                        "\n",
                        v->v.s);
                return ((void *)0);
            } while (0);
        return f;
    case TSP_PAIR:
        if (!(f = tisp_eval(st, env, ((v)->v.p.car))))
            return ((void *)0);
        return eval_proc(st, env, f, ((v)->v.p.cdr));
    default:
        return v;
    }
}

functions.tisp_print:
void tisp_print(FILE *f, Val v)
{
    switch (v->t)
    {
    case TSP_NONE:
        fputs("Void", f);
        break;
    case TSP_NIL:
        fputs("Nil", f);
        break;
    case TSP_INT:
        fprintf(f, "%d", (int)((v)->v.n.num));
        break;
    case TSP_DEC:
        fprintf(f, "%.15g", ((v)->v.n.num));
        if (((v)->v.n.num) == (int)((v)->v.n.num))
            fprintf(f, ".0");
        break;
    case TSP_RATIO:
        fprintf(f, "%d/%d", (int)((v)->v.n.num), (int)((v)->v.n.den));
        break;
    case TSP_STR:
    case TSP_SYM:
        fputs(v->v.s, f);
        break;
    case TSP_FUNC:
    case TSP_MACRO:
        fprintf(f, "#<%s%s%s>", v->t == TSP_FUNC ? "function" : "macro", v->v.f.name ? ":" : "",
                v->v.f.name ? v->v.f.name : "");
        break;
    case TSP_PRIM:
        fprintf(f, "#<primitive:%s>", v->v.pr.name);
        break;
    case TSP_FORM:
        fprintf(f, "#<form:%s>", v->v.pr.name);
        break;
    case TSP_REC:
        putc('{', f);
        for (Rec r = v->v.r; r; r = r->next)
            for (int i = 0, c = 0; c < r->size; i++)
                if (r->items[i].key)
                {
                    c++;
                    fprintf(f, " %s: ", r->items[i].key);
                    tisp_print(f, r->items[i].val);
                }
                else if (c == 64)
                {
                    fputs(" ...", f);
                    break;
                }
        fputs(" }", f);
        break;
    case TSP_PAIR:
        putc('(', f);
        tisp_print(f, ((v)->v.p.car));
        for (v = ((v)->v.p.cdr); !((v)->t == TSP_NIL); v = ((v)->v.p.cdr))
        {
            if (v->t == TSP_PAIR)
            {
                putc(' ', f);
                tisp_print(f, ((v)->v.p.car));
            }
            else
            {
                fputs(" . ", f);
                tisp_print(f, v);
                break;
            }
        }
        putc(')', f);
        break;
    default:
        fprintf(stderr, "; tisp: could not print value type %s\n", tsp_type_str(v->t));
    }
}

