functions.val_string:
static Val val_string(Tsp st, Val args, MkFn mk_fn)
{
    Val v;
    char s[43], *ret = calloc(1, sizeof(char));
    int len = 1;
    for (; args->t == TSP_PAIR; args = ((args)->v.p.cdr))
    {
        v = ((args)->v.p.car);
        switch (v->t)
        {
        case TSP_NONE:
            break;
        case TSP_NIL:
            len += 4;
            ret = realloc(ret, len * sizeof(char));
            strcat(ret, "Nil");
            break;
        case TSP_INT:
            snprintf(s, 21, "%d", (int)v->v.n.num);
            len += strlen(s);
            s[len] = '\0';
            ret = realloc(ret, len * sizeof(char));
            strcat(ret, s);
            break;
        case TSP_DEC:
            snprintf(s, 22, "%.15g", v->v.n.num);
            len += strlen(s);
            s[len] = '\0';
            ret = realloc(ret, len * sizeof(char));
            strcat(ret, s);
            break;
        case TSP_RATIO:
            snprintf(s, 43, "%d/%d", (int)v->v.n.num, (int)v->v.n.den);
            len += strlen(s);
            s[len] = '\0';
            ret = realloc(ret, len * sizeof(char));
            strcat(ret, s);
            break;
        case TSP_STR:
        case TSP_SYM:
            len += strlen(v->v.s);
            ret = realloc(ret, len * sizeof(char));
            strcat(ret, v->v.s);
            break;
        case TSP_PAIR:
        default:
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "could not convert type %s into string"
                        "\n",
                        tsp_type_str(v->t));
                return ((void *)0);
            } while (0);
        }
    }
    v = mk_fn(st, ret);
    free(ret);
    return v;
}

