functions.form_strformat:
static Val form_strformat(Tsp st, Rec env, Val args)
{
    char *ret, *str;
    int ret_len, ret_cap, pos = 0;
    Val v;
    do
    {
        if (1 > -1 && tsp_lstlen(args) != 1)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "%s: expected %d argument%s, received %d"
                        "\n",
                        "strformat", 1, 1 > 1 ? "s" : "", tsp_lstlen(args));
                return ((void *)0);
            } while (0);
    } while (0);
    do
    {
        if (!(((args)->v.p.car)->t & (TSP_STR)))
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "strformat"
                        ": expected %s, received %s"
                        "\n",
                        tsp_type_str(TSP_STR), tsp_type_str(((args)->v.p.car)->t));
                return ((void *)0);
            } while (0);
    } while (0);
    str = ((args)->v.p.car)->v.s;
    ret_len = strlen(str), ret_cap = 2 * ret_len;
    if (!(ret = malloc(sizeof(char) * ret_cap)))
        perror("; malloc"), exit(1);
    while (*str)
        if (*str == '{' && str[1] != '{')
        {
            int l;
            char *file = st->file;
            size_t filec = st->filec;
            st->file = ++str, st->filec = 0;
            if (!(v = read_pair(st, '}')))
                return ((void *)0);
            str += st->filec;
            st->file = file, st->filec = filec;
            if (!(v = tisp_eval_list(st, env, v)))
                return ((void *)0);
            if (!(v = val_string(st, v, mk_str)))
                return ((void *)0);
            l = strlen(v->v.s);
            ret_len += l;
            if (ret_len >= ret_cap)
                if (!(ret = realloc(ret, ret_cap *= 2)))
                    perror("; realloc"), exit(1);
            memcpy(ret + pos, v->v.s, l);
            pos += l;
        }
        else
        {
            if (*str == '{' || *str == '}')
                str++;
            ret[pos++] = *str++;
        }
    ret[pos] = '\0';
    return mk_str(st, ret);
}

