functions.count_parens:
static int count_parens(char *s, int len)
{
    int pcount = 0, bcount = 0, ccount = 0;
    for (int i = 0; i < len && s[i]; i++)
    {
        switch (s[i])
        {
        case '(':
            pcount++;
            break;
        case '[':
            bcount++;
            break;
        case '{':
            ccount++;
            break;
        case ')':
            pcount--;
            break;
        case ']':
            bcount--;
            break;
        case '}':
            ccount--;
            break;
        }
    }
    if (pcount)
        return pcount;
    if (bcount)
        return bcount;
    return ccount;
}

functions.read_file:
static char *read_file(char *fname)
{
    char buf[8192], *file = ((void *)0);
    int len = 0, n, fd, parens = 0;
    if (!fname)
        fd = 0;
    else if ((fd = open(fname, 00)) < 0)
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "could not find file '%s'"
                    "\n",
                    fname);
            return ((void *)0);
        } while (0);
    while ((n = read(fd, buf, sizeof(buf))) > 0)
    {
        file = realloc(file, len + n + 1);
        if (!file)
            perror("; realloc"), exit(1);
        memcpy(file + len, buf, n);
        len += n;
        file[len] = '\0';
        if (fd == 0 && (parens += count_parens(buf, n)) <= 0)
            break;
    }
    if (fd)
        close(fd);
    if (n < 0)
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "could not read file '%s'"
                    "\n",
                    fname);
            return ((void *)0);
        } while (0);
    return file;
}

functions.prim_write:
static Val prim_write(Tsp st, Rec env, Val args)
{
    FILE *f;
    const char *mode = "w";
    do
    {
        if (tsp_lstlen(args) < 2)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "%s: expected at least %d argument%s, received %d"
                        "\n",
                        "write", 2, 2 > 1 ? "s" : "", tsp_lstlen(args));
                return ((void *)0);
            } while (0);
    } while (0);
    if (!((((((args)->v.p.cdr))->v.p.car))->t == TSP_NIL))
        mode = "a";
    if (((args)->v.p.car)->t == TSP_SYM)
        f = !strncmp(((args)->v.p.car)->v.s, "stdout", 7) ? stdout : stderr;
    else if (((args)->v.p.car)->t != TSP_STR)
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "write: expected file name as string, received %s"
                    "\n",
                    tsp_type_str(((args)->v.p.car)->t));
            return ((void *)0);
        } while (0);
    else if (!(f = fopen(((args)->v.p.car)->v.s, mode)))
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "write: could not load file '%s'"
                    "\n",
                    ((args)->v.p.car)->v.s);
            return ((void *)0);
        } while (0);
    if (f == stderr && strncmp(((args)->v.p.car)->v.s, "stderr", 7))
        do
        {
            fprintf(stderr, "; tisp: error: "
                            "write: expected file name as string, or symbol stdout/stderr"
                            "\n");
            return ((void *)0);
        } while (0);
    for (args = ((((args)->v.p.cdr))->v.p.cdr); !((args)->t == TSP_NIL); args = ((args)->v.p.cdr))
        tisp_print(f, ((args)->v.p.car));
    if (f == stdout || f == stderr)
        fflush(f);
    else
        fclose(f);
    return st->none;
}

functions.prim_read:
static Val prim_read(Tsp st, Rec env, Val args)
{
    char *file, *fname = ((void *)0);
    do
    {
        if (tsp_lstlen(args) > 1)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
