                        "\n",
                        "read", 1, 1 > 1 ? "s" : "", tsp_lstlen(args));
                return ((void *)0);
            } while (0);
    } while (0);
    if (tsp_lstlen(args) == 1)
    {
        do
        {
            if (!(((args)->v.p.car)->t & (TSP_STR)))
                do
                {
                    fprintf(stderr,
                            "; tisp: error: "
                            "read"
                            ": expected %s, received %s"
                            "\n",
                            tsp_type_str(TSP_STR), tsp_type_str(((args)->v.p.car)->t));
                    return ((void *)0);
                } while (0);
        } while (0);
        fname = ((args)->v.p.car)->v.s;
    }
    if (!(file = read_file(fname)))
        return st->nil;
    return mk_str(st, file);
}

functions.prim_parse:
static Val prim_parse(Tsp st, Rec env, Val args)
{
    Val ret, expr;
    char *file = st->file;
    size_t filec = st->filec;
    do
    {
        if (1 > -1 && tsp_lstlen(args) != 1)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "%s: expected %d argument%s, received %d"
                        "\n",
                        "parse", 1, 1 > 1 ? "s" : "", tsp_lstlen(args));
                return ((void *)0);
            } while (0);
    } while (0);
    expr = ((args)->v.p.car);
    if (((expr)->t == TSP_NIL))
        return mk_sym(st, "quit");
    do
    {
        if (!(expr->t & (TSP_STR)))
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "parse"
                        ": expected %s, received %s"
                        "\n",
                        tsp_type_str(TSP_STR), tsp_type_str(expr->t));
                return ((void *)0);
            } while (0);
    } while (0);
    st->file = expr->v.s;
    st->filec = 0;
    ret = mk_pair(mk_sym(st, "do"), st->nil);
    for (Val pos = ret; st->file[st->filec + 0] && (expr = tisp_read_line(st, 0)); pos = ((pos)->v.p.cdr))
        ((pos)->v.p.cdr) = mk_pair(expr, st->nil);
    st->file = file;
    st->filec = filec;
    if (((ret)->v.p.cdr)->t == TSP_PAIR && ((((((ret)->v.p.cdr))->v.p.cdr))->t == TSP_NIL))
        return ((((ret)->v.p.cdr))->v.p.car);
    return ret;
}

functions.prim_load:
static Val prim_load(Tsp st, Rec env, Val args)
{
    Val tib;
    void (*tibenv)(Tsp);
    char name[4096];
    const char *paths[] = {"/usr/local/lib/tisp/pkgs/", "/usr/lib/tisp/pkgs/", "./", ((void *)0)};
    do
    {
        if (1 > -1 && tsp_lstlen(args) != 1)
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "%s: expected %d argument%s, received %d"
                        "\n",
                        "load", 1, 1 > 1 ? "s" : "", tsp_lstlen(args));
                return ((void *)0);
            } while (0);
    } while (0);
    tib = ((args)->v.p.car);
    do
    {
        if (!(tib->t & (TSP_STR)))
            do
            {
                fprintf(stderr,
                        "; tisp: error: "
                        "load"
                        ": expected %s, received %s"
                        "\n",
                        tsp_type_str(TSP_STR), tsp_type_str(tib->t));
                return ((void *)0);
            } while (0);
    } while (0);
    for (int i = 0; paths[i]; i++)
    {
        strcpy(name, paths[i]);
        strcat(name, tib->v.s);
        strcat(name, ".tsp");
        if (access(name, 4) != -1)
        {
            char *file = read_file(name);
            Val body = prim_parse(st, env, mk_pair(mk_sym(st, file), st->nil));
            tisp_eval_body(st, env, body);
            return st->none;
        }
    }
    if (!(st->libh = realloc(st->libh, (st->libhc + 1) * sizeof(void *))))
        perror("; realloc"), exit(1);
    memset(name, 0, sizeof(name));
    strcpy(name, "libtib");
    strcat(name, tib->v.s);
    strcat(name, ".so");
    if (!(st->libh[st->libhc] = dlopen(name, 0x00001)))
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "load: could not load '%s':\n; %s"
                    "\n",
                    tib->v.s, dlerror());
            return ((void *)0);
        } while (0);
    dlerror();
    memset(name, 0, sizeof(name));
    strcpy(name, "tib_env_");
    strcat(name, tib->v.s);
    tibenv = dlsym(st->libh[st->libhc], name);
    if (dlerror())
        do
        {
            fprintf(stderr,
                    "; tisp: error: "
                    "load: could not run '%s':\n; %s"
                    "\n",
                    tib->v.s, dlerror());
            return ((void *)0);
        } while (0);
    (*tibenv)(st);
    st->libhc++;
    return st->none;
}

